insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('timur-east', 'Timur''s Eastern Campaign', 'What if Timur had survived and continued his eastern campaign against Ming China?', 1405, '1400', '{"id":"timur-east","title":"Timur''s Eastern Campaign","subtitle":"Otrar, February 1405","question":"What if Timur had survived and continued his eastern campaign against Ming China?","mapKey":"1400","start":{"y":1405,"m":0},"era":"medieval","artHue":205,"background":["By 1404 Timur (Tamerlane) had built an empire from Anatolia to the borders of India. In 1402 he crushed the Ottomans at Ankara and captured Sultan Bayezid I, plunging the Ottoman state into a decade-long civil war (the Interregnum).","Returning to Samarkand, Timur assembled a large army for a winter campaign against the Ming dynasty, whose Yongle Emperor had usurped the throne in 1402 and had treated Timurid envoys as tributaries.","The army marched north-east in the bitter winter of 1404–05. At Otrar, on the Syr Darya, Timur fell ill and died on 18 February 1405, aged about 68. The campaign was abandoned and his succession dissolved into conflict among his sons and grandsons."],"sourcesNote":"Background follows standard accounts (e.g. B. F. Manz, \"The Rise and Rule of Tamerlane\", 1989). Borders: historical-basemaps c.1400 with editorial corrections for China.","sensitivity":"Timur''s campaigns caused enormous loss of life (e.g. Delhi 1398, Isfahan 1387, Baghdad 1401). The simulation models political and economic consequences; it does not celebrate conquest.","focusCountries":["Timurid Empire","Ming Empire","Ottoman Empire","Northern Yuan","Mamluke Sultanate","Byzantine Empire"],"recommended":"Timurid Empire","characters":[{"name":"Timur (Tamerlane)","role":"Emir of the Timurid Empire","years":"c.1336–1405","bio":"Turco-Mongol conqueror; never took the title of khan, ruling through Chinggisid puppet khans.","country":"Timurid Empire"},{"name":"Shah Rukh","role":"Timur''s youngest son","years":"1377–1447","bio":"Governor of Khorasan; historically emerged victorious from the succession struggle by 1409.","country":"Timurid Empire"},{"name":"Pir Muhammad","role":"Timur''s designated heir (grandson)","years":"1374–1407","bio":"Named successor on Timur''s deathbed; assassinated in 1407.","country":"Timurid Empire"},{"name":"Yongle Emperor (Zhu Di)","role":"Emperor of Ming China","years":"1360–1424","bio":"Usurped the throne in 1402; sponsored Zheng He''s voyages and campaigns against the Mongols.","country":"Ming Empire"},{"name":"Mehmed Çelebi","role":"Ottoman prince","years":"c.1389–1421","bio":"Won the Ottoman Interregnum in 1413 and reunited the state as Mehmed I.","country":"Ottoman Empire"}],"originalTimeline":[{"date":{"y":1402,"m":6},"title":"Battle of Ankara","text":"Timur defeats and captures Ottoman Sultan Bayezid I.","countries":["Timurid Empire","Ottoman Empire"]},{"date":{"y":1404,"m":11},"title":"March on China begins","text":"Timur leaves Samarkand with a large army heading for Ming China.","countries":["Timurid Empire"]},{"date":{"y":1405,"m":1},"title":"Death of Timur at Otrar","text":"Timur dies of illness; the campaign is abandoned.","countries":["Timurid Empire"]},{"date":{"y":1405,"m":6},"title":"Zheng He''s first voyage","text":"The Ming treasure fleet sails for the Indian Ocean.","countries":["Ming Empire"]},{"date":{"y":1409,"m":4},"title":"Shah Rukh secures Samarkand","text":"After four years of succession war Shah Rukh controls the Timurid core.","countries":["Timurid Empire"]},{"date":{"y":1413,"m":6},"title":"End of the Ottoman Interregnum","text":"Mehmed I reunites the Ottoman state.","countries":["Ottoman Empire"]},{"date":{"y":1421,"m":1},"title":"Beijing becomes Ming capital","text":"The Yongle Emperor moves the capital north to Beijing.","countries":["Ming Empire"]}],"decisions":[{"id":"timur_fate","question":"Does Timur survive the winter at Otrar?","context":"Historically he died on 18 February 1405.","options":[{"id":"dies","label":"Timur dies at Otrar","description":"Documented history: the succession crisis begins immediately.","historical":true},{"id":"survives","label":"Timur recovers","description":"Timur lives (with failing health) and can continue the campaign."}]},{"id":"campaign","question":"What does the surviving Timur do next?","context":"Only relevant if Timur survives.","dependsOn":{"decision":"timur_fate","option":"survives"},"options":[{"id":"invade","label":"Press on into Ming China","description":"War with the Ming. Outcome depends on supply across the Tarim/Gobi routes, Ming defences and Timurid cohesion."},{"id":"consolidate","label":"Return and settle the succession","description":"Timur names a single heir and spends his last years consolidating the empire."}]},{"id":"ottomans","question":"How do the Ottomans emerge from the Interregnum?","context":"Historically Mehmed I won in 1413.","options":[{"id":"historical","label":"Civil war continues (historical)","description":"The Ottomans remain weakened by internal strife for years.","historical":true},{"id":"quick","label":"Rapid reunification","description":"One prince quickly reunifies the state, restoring stability."}]}],"consequences":[{"decision":"timur_fate","option":"dies","text":"Succession crisis fires; Timurid stability and legitimacy fall sharply; rival claimants may break away."},{"decision":"timur_fate","option":"survives","text":"Timur stays in power with low health; legitimacy remains high while he lives, but every month carries mortality risk."},{"decision":"campaign","option":"invade","text":"A war against the Ming begins. Logistics over long desert routes heavily penalise Timurid supply."},{"decision":"campaign","option":"consolidate","text":"A designated heir gains legitimacy, reducing the chance of fragmentation when Timur dies."},{"decision":"ottomans","option":"quick","text":"Ottoman stability is restored — Byzantium faces renewed pressure much sooner."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('timur-east', 'timur_fate', 'Does Timur survive the winter at Otrar?', '[{"id":"dies","label":"Timur dies at Otrar","description":"Documented history: the succession crisis begins immediately.","historical":true},{"id":"survives","label":"Timur recovers","description":"Timur lives (with failing health) and can continue the campaign."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('timur-east', 'campaign', 'What does the surviving Timur do next?', '[{"id":"invade","label":"Press on into Ming China","description":"War with the Ming. Outcome depends on supply across the Tarim/Gobi routes, Ming defences and Timurid cohesion."},{"id":"consolidate","label":"Return and settle the succession","description":"Timur names a single heir and spends his last years consolidating the empire."}]'::jsonb, '{"decision":"timur_fate","option":"survives"}'::jsonb) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('timur-east', 'ottomans', 'How do the Ottomans emerge from the Interregnum?', '[{"id":"historical","label":"Civil war continues (historical)","description":"The Ottomans remain weakened by internal strife for years.","historical":true},{"id":"quick","label":"Rapid reunification","description":"One prince quickly reunifies the state, restoring stability."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
