insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('waterloo', 'The Hundred Days', 'What if Napoleon had won at Waterloo?', 1815, '1815', '{"id":"waterloo","title":"The Hundred Days","subtitle":"Belgium, June 1815","question":"What if Napoleon had won at Waterloo?","mapKey":"1815","start":{"y":1815,"m":5},"era":"industrial","artHue":220,"background":["In March 1815 Napoleon escaped exile on Elba and retook power in France. The Congress of Vienna powers declared him an outlaw and formed the Seventh Coalition.","Napoleon struck first, invading present-day Belgium to defeat Wellington''s Anglo-allied army and Blücher''s Prussians before Austrian and Russian armies could arrive.","On 18 June 1815, at Waterloo, Wellington held long enough for Prussian forces to arrive on the French flank. The French army broke; Napoleon abdicated on 22 June and was exiled to Saint Helena."],"sourcesNote":"Background follows standard accounts (e.g. A. Roberts, \"Napoleon the Great\", 2014). Borders: historical-basemaps 1815.","focusCountries":["France","United Kingdom of Great Britain and Ireland","Prussia","Austrian Empire","Russian Empire","Spain"],"recommended":"France","characters":[{"name":"Napoleon Bonaparte","role":"Emperor of the French","years":"1769–1821","bio":"Returned from Elba for the Hundred Days.","country":"France"},{"name":"Arthur Wellesley, Duke of Wellington","role":"Anglo-allied commander","years":"1769–1852","bio":"Commanded the Anglo-Dutch-German army at Waterloo.","country":"United Kingdom of Great Britain and Ireland"},{"name":"Gebhard von Blücher","role":"Prussian field marshal","years":"1742–1819","bio":"His army''s arrival decided the battle.","country":"Prussia"},{"name":"Klemens von Metternich","role":"Austrian foreign minister","years":"1773–1859","bio":"Architect of the post-Napoleonic order.","country":"Austrian Empire"},{"name":"Alexander I","role":"Emperor of Russia","years":"1777–1825","bio":"Leading force of the coalition; promoter of the Holy Alliance.","country":"Russian Empire"}],"originalTimeline":[{"date":{"y":1815,"m":2},"title":"Napoleon returns from Elba","text":"Napoleon lands in France and reaches Paris on 20 March.","countries":["France"]},{"date":{"y":1815,"m":5},"title":"Battle of Waterloo","text":"French defeat by Wellington and Blücher (18 June).","countries":["France","United Kingdom of Great Britain and Ireland","Prussia"]},{"date":{"y":1815,"m":5},"title":"Second abdication","text":"Napoleon abdicates on 22 June and is exiled to Saint Helena.","countries":["France"]},{"date":{"y":1815,"m":8},"title":"Holy Alliance","text":"Russia, Austria and Prussia form a conservative alliance.","countries":["Russian Empire","Austrian Empire","Prussia"]},{"date":{"y":1815,"m":10},"title":"Second Treaty of Paris","text":"France reduced to 1790 borders and occupied.","countries":["France"]},{"date":{"y":1830,"m":6},"title":"July Revolution","text":"The Bourbon Restoration falls in France.","countries":["France"]}],"decisions":[{"id":"battle","question":"What happens at Waterloo?","context":"18 June 1815.","options":[{"id":"defeat","label":"French defeat (historical)","description":"Napoleon abdicates; the Bourbons return.","historical":true},{"id":"victory","label":"Decisive French victory","description":"Wellington is beaten before Blücher arrives. The Coalition armies remain in the field."},{"id":"stalemate","label":"Indecisive battle","description":"Both sides withdraw; the war drags on."}]},{"id":"coalition","question":"How does the Coalition react to a French success?","context":"Applies if France is not defeated.","dependsOn":{"decision":"battle","option":"victory"},"options":[{"id":"fight","label":"Coalition fights on","description":"Austria and Russia continue to mobilise."},{"id":"negotiate","label":"Britain seeks a negotiated peace","description":"War-weary Britain leaves the coalition, isolating Prussia."}]}],"consequences":[{"decision":"battle","option":"defeat","text":"France becomes a constitutional monarchy, loses stability and pays reparations."},{"decision":"battle","option":"victory","text":"France gains legitimacy and morale; Britain and Prussia lose manpower; the war continues dynamically."},{"decision":"battle","option":"stalemate","text":"War exhaustion rises on all sides; the war continues."},{"decision":"coalition","option":"negotiate","text":"Britain signs white peace with France; Prussia and Austria fight on alone."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('waterloo', 'battle', 'What happens at Waterloo?', '[{"id":"defeat","label":"French defeat (historical)","description":"Napoleon abdicates; the Bourbons return.","historical":true},{"id":"victory","label":"Decisive French victory","description":"Wellington is beaten before Blücher arrives. The Coalition armies remain in the field."},{"id":"stalemate","label":"Indecisive battle","description":"Both sides withdraw; the war drags on."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('waterloo', 'coalition', 'How does the Coalition react to a French success?', '[{"id":"fight","label":"Coalition fights on","description":"Austria and Russia continue to mobilise."},{"id":"negotiate","label":"Britain seeks a negotiated peace","description":"War-weary Britain leaves the coalition, isolating Prussia."}]'::jsonb, '{"decision":"battle","option":"victory"}'::jsonb) on conflict (scenario_id, decision_key) do nothing;
