insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('rome-endures', 'The Eternal Empire', 'What if the Roman Empire had never collapsed?', 400, '400', '{"id":"rome-endures","title":"The Eternal Empire","subtitle":"The Roman world, AD 400","question":"What if the Roman Empire had never collapsed?","mapKey":"400","start":{"y":400,"m":0},"era":"classical","artHue":8,"background":["At Theodosius I''s death in 395 the Roman Empire was divided permanently between his sons: Arcadius in the East, Honorius in the West.","The West faced Gothic federates, a Rhine frontier under pressure from Vandals, Alans and Suebi (who crossed in 406), fiscal exhaustion and civil wars between generals.","Rome was sacked by the Visigoths in 410; the last Western emperor, Romulus Augustulus, was deposed in 476. The Eastern Empire endured for another thousand years."],"sourcesNote":"Background follows standard accounts (e.g. P. Heather, \"The Fall of the Roman Empire\", 2005). Borders: historical-basemaps AD 400.","focusCountries":["Western Roman Empire","Eastern Roman Empire","Hunnic Empire","Visigoths","Persia","Franks"],"recommended":"Western Roman Empire","characters":[{"name":"Honorius","role":"Western Roman Emperor","years":"384–423","bio":"Ruled from Milan and later Ravenna.","country":"Western Roman Empire"},{"name":"Stilicho","role":"Magister militum of the West","years":"c.359–408","bio":"Half-Vandal general who defended the West; executed in 408.","country":"Western Roman Empire"},{"name":"Arcadius","role":"Eastern Roman Emperor","years":"377–408","bio":"Ruled from Constantinople.","country":"Eastern Roman Empire"},{"name":"Alaric I","role":"King of the Visigoths","years":"c.370–410","bio":"Sacked Rome in 410.","country":"Visigoths"},{"name":"Yazdegerd I","role":"Sasanian King of Kings","years":"r.399–420","bio":"Kept peace with Rome.","country":"Persia"}],"originalTimeline":[{"date":{"y":406,"m":11},"title":"Rhine crossing","text":"Vandals, Alans and Suebi cross the frozen Rhine into Gaul.","countries":["Western Roman Empire"]},{"date":{"y":408,"m":7},"title":"Execution of Stilicho","text":"The West loses its most capable general.","countries":["Western Roman Empire"]},{"date":{"y":410,"m":7},"title":"Sack of Rome","text":"Alaric''s Visigoths sack the city of Rome.","countries":["Western Roman Empire","Visigoths"]},{"date":{"y":451,"m":5},"title":"Battle of the Catalaunian Plains","text":"Romans and Visigoths halt Attila.","countries":["Western Roman Empire","Hunnic Empire"]},{"date":{"y":476,"m":8},"title":"Deposition of Romulus Augustulus","text":"Conventional end of the Western Empire.","countries":["Western Roman Empire"]}],"decisions":[{"id":"stilicho","question":"Is Stilicho executed in 408?","context":"His death removed the West''s best defender.","options":[{"id":"executed","label":"Stilicho executed (historical)","description":"Court intrigue destroys the West''s military leadership.","historical":true},{"id":"spared","label":"Stilicho survives and reforms the army","description":"The Western army is rebuilt with stronger discipline."}]},{"id":"reunify","question":"Do East and West cooperate?","context":"The two courts were often rivals.","options":[{"id":"rivals","label":"Rival courts (historical)","description":"Limited cooperation.","historical":true},{"id":"alliance","label":"Permanent alliance","description":"Constantinople subsidises and defends the West."}]},{"id":"fiscal","question":"Does the West reform its finances?","context":"Tax collapse undermined the army.","options":[{"id":"none","label":"No reform (historical)","description":"Fiscal decline continues.","historical":true},{"id":"reform","label":"Tax and land reform","description":"Higher tax efficiency, lower inflation."}]}],"consequences":[{"decision":"stilicho","option":"spared","text":"Western Roman military quality and morale rise; Visigoth relations improve."},{"decision":"reunify","option":"alliance","text":"East and West sign an alliance and mutual guarantee."},{"decision":"fiscal","option":"reform","text":"Western tax efficiency +15% (permanent modifier), inflation reduced."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('rome-endures', 'stilicho', 'Is Stilicho executed in 408?', '[{"id":"executed","label":"Stilicho executed (historical)","description":"Court intrigue destroys the West''s military leadership.","historical":true},{"id":"spared","label":"Stilicho survives and reforms the army","description":"The Western army is rebuilt with stronger discipline."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('rome-endures', 'reunify', 'Do East and West cooperate?', '[{"id":"rivals","label":"Rival courts (historical)","description":"Limited cooperation.","historical":true},{"id":"alliance","label":"Permanent alliance","description":"Constantinople subsidises and defends the West."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('rome-endures', 'fiscal', 'Does the West reform its finances?', '[{"id":"none","label":"No reform (historical)","description":"Fiscal decline continues.","historical":true},{"id":"reform","label":"Tax and land reform","description":"Higher tax efficiency, lower inflation."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
