insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('rome-endures', 476, 8, 'Deposition of Romulus Augustulus', 'Conventional end of the Western Empire.', '{"Western Roman Empire"}', true);
insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('mongol-unity', 'One Ulus', 'What if the Mongol Empire had remained united?', 1279, '1279', '{"id":"mongol-unity","title":"One Ulus","subtitle":"The Mongol world, 1279","question":"What if the Mongol Empire had remained united?","mapKey":"1279","start":{"y":1279,"m":2},"era":"medieval","artHue":38,"background":["After Great Khan Möngke died in 1259, a succession war between Kublai and Ariq Böke broke the unity of the Mongol Empire. By the 1260s it had split into four khanates: the Yuan, the Golden Horde, the Ilkhanate and the Chagatai Khanate.","In 1279 Kublai''s Yuan dynasty completed the conquest of Song China. The western khanates fought each other — notably the Golden Horde against the Ilkhanate over the Caucasus."],"sourcesNote":"Background follows standard accounts (e.g. T. May, \"The Mongol Empire\", 2018). Borders: historical-basemaps 1279 (Yuan label corrected).","sensitivity":"The Mongol conquests caused catastrophic loss of life and destruction across Eurasia; this scenario explores counterfactual political structures, not glorification of conquest.","focusCountries":["Yuan Dynasty","Khanate of the Golden Horde","Ilkhanate","Chagatai Khanate","Mamluke Sultanate","Byzantine Empire"],"recommended":"Yuan Dynasty","characters":[{"name":"Kublai Khan","role":"Great Khan, Emperor of Yuan","years":"1215–1294","bio":"Founded the Yuan dynasty and conquered the Song.","country":"Yuan Dynasty"},{"name":"Abaqa Khan","role":"Ilkhan","years":"1234–1282","bio":"Ruled Persia; allied with Kublai against the Golden Horde.","country":"Ilkhanate"},{"name":"Möngke-Temür","role":"Khan of the Golden Horde","years":"r.1266–1280","bio":"Ruled the western steppe.","country":"Khanate of the Golden Horde"},{"name":"Qaidu","role":"Ruler in Central Asia","years":"c.1230–1301","bio":"Long-time rival of Kublai.","country":"Chagatai Khanate"},{"name":"Qalawun","role":"Mamluk Sultan","years":"r.1279–1290","bio":"Defeated the Ilkhanate at Homs in 1281.","country":"Mamluke Sultanate"}],"originalTimeline":[{"date":{"y":1260,"m":8},"title":"Ain Jalut","text":"The Mamluks defeat the Mongols in Palestine.","countries":["Mamluke Sultanate"]},{"date":{"y":1279,"m":2},"title":"Battle of Yamen","text":"The last Song resistance is destroyed.","countries":["Yuan Dynasty"]},{"date":{"y":1281,"m":9},"title":"Second Battle of Homs","text":"The Mamluks defeat the Ilkhanate.","countries":["Ilkhanate","Mamluke Sultanate"]},{"date":{"y":1281,"m":7},"title":"Second invasion of Japan fails","text":"The Yuan fleet is destroyed by a typhoon.","countries":["Yuan Dynasty"]},{"date":{"y":1294,"m":1},"title":"Death of Kublai","text":"Kublai dies; the khanates drift further apart.","countries":["Yuan Dynasty"]}],"decisions":[{"id":"unity","question":"Do the khanates accept a single Great Khan?","context":"Historically the empire had fractured by the 1260s.","options":[{"id":"divided","label":"Four khanates (historical)","description":"The khanates act independently.","historical":true},{"id":"federation","label":"Federation under Kublai","description":"The khanates become autonomous vassals of the Great Khan."},{"id":"unified","label":"Fully unified empire","description":"All four khanates merge into a single state — vast but hard to govern."}]}],"consequences":[{"decision":"unity","option":"federation","text":"Golden Horde, Ilkhanate and Chagatai become vassals of the Yuan with good relations."},{"decision":"unity","option":"unified","text":"All four khanates merge into one country with high overextension unrest."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('mongol-unity', 'unity', 'Do the khanates accept a single Great Khan?', '[{"id":"divided","label":"Four khanates (historical)","description":"The khanates act independently.","historical":true},{"id":"federation","label":"Federation under Kublai","description":"The khanates become autonomous vassals of the Great Khan."},{"id":"unified","label":"Fully unified empire","description":"All four khanates merge into a single state — vast but hard to govern."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('mongol-unity', 1260, 8, 'Ain Jalut', 'The Mamluks defeat the Mongols in Palestine.', '{"Mamluke Sultanate"}', true);
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('mongol-unity', 1279, 2, 'Battle of Yamen', 'The last Song resistance is destroyed.', '{"Yuan Dynasty"}', true);
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('mongol-unity', 1281, 9, 'Second Battle of Homs', 'The Mamluks defeat the Ilkhanate.', '{"Ilkhanate","Mamluke Sultanate"}', true);
