insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('mongol-unity', 1294, 1, 'Death of Kublai', 'Kublai dies; the khanates drift further apart.', '{"Yuan Dynasty"}', true);
insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('different-peace-1945', 'A Different Peace', 'What if the Second World War had ended differently — with a cooperative post-war order instead of the Cold War?', 1945, '1945', '{"id":"different-peace-1945","title":"A Different Peace","subtitle":"The world after 1945","question":"What if the Second World War had ended differently — with a cooperative post-war order instead of the Cold War?","mapKey":"1945","start":{"y":1945,"m":8},"era":"modern","artHue":220,"background":["The Second World War ended in Europe on 8 May 1945 and in Asia with Japan''s surrender announced on 15 August 1945, after the atomic bombings of Hiroshima and Nagasaki and the Soviet declaration of war.","The war killed an estimated 70–85 million people, including six million Jews murdered in the Holocaust by Nazi Germany and its collaborators, and millions of other victims of genocide, occupation and war crimes.","Wartime cooperation between the United States, the Soviet Union and the United Kingdom quickly broke down. Germany and Korea were divided, and the Cold War shaped the next four decades."],"sourcesNote":"Background follows standard accounts (e.g. T. Judt, \"Postwar\", 2005; United States Holocaust Memorial Museum). Borders: historical-basemaps 1945, including occupation zones.","sensitivity":"This scenario starts after the defeat of Nazi Germany and Imperial Japan. The Holocaust and wartime atrocities are documented facts and are never altered or minimised. Authoritarian regimes are modelled with explicit legitimacy and unrest costs.","focusCountries":["United States","USSR","United Kingdom","France","China","Poland"],"recommended":"United States","characters":[{"name":"Harry S. Truman","role":"President of the United States","years":"1884–1972","bio":"President from April 1945.","country":"United States"},{"name":"Joseph Stalin","role":"Leader of the USSR","years":"1878–1953","bio":"Dictator responsible for mass repression, deportations and the Gulag system.","country":"USSR"},{"name":"Clement Attlee","role":"Prime Minister of the UK","years":"1883–1967","bio":"Elected July 1945; built the welfare state.","country":"United Kingdom"},{"name":"Charles de Gaulle","role":"Head of the French Provisional Government","years":"1890–1970","bio":"Led Free France.","country":"France"}],"originalTimeline":[{"date":{"y":1945,"m":4},"title":"Victory in Europe","text":"Germany surrenders unconditionally (8 May).","countries":[]},{"date":{"y":1945,"m":7},"title":"Japan surrenders","text":"Surrender announced 15 August; signed 2 September.","countries":[]},{"date":{"y":1945,"m":9},"title":"United Nations founded","text":"The UN Charter enters into force (24 October).","countries":[]},{"date":{"y":1947,"m":5},"title":"Marshall Plan announced","text":"US aid to rebuild Europe; the USSR refuses participation.","countries":["United States","USSR"]},{"date":{"y":1948,"m":5},"title":"Berlin Blockade","text":"The USSR blockades West Berlin; Allied airlift follows.","countries":["USSR","United States"]},{"date":{"y":1949,"m":3},"title":"NATO founded","text":"Western military alliance formed.","countries":["United States","United Kingdom","France"]},{"date":{"y":1950,"m":5},"title":"Korean War begins","text":"North Korea invades the South.","countries":[]}],"decisions":[{"id":"order","question":"What post-war order emerges?","context":"Historically the Grand Alliance fractured into the Cold War.","options":[{"id":"coldwar","label":"Cold War (historical)","description":"Rival blocs, low trust between the US and USSR.","historical":true},{"id":"concert","label":"Great-power concert","description":"The Allies keep cooperating through the UN; trade agreements and non-aggression pacts."}]},{"id":"aid","question":"How is reconstruction funded?","context":"The Marshall Plan was offered to all of Europe but rejected by the Soviet bloc.","options":[{"id":"west","label":"Western Europe only (historical)","description":"Aid strengthens the Western bloc.","historical":true},{"id":"all","label":"Pan-European reconstruction","description":"Aid reaches all of Europe including the Soviet zone."}]}],"consequences":[{"decision":"order","option":"coldwar","text":"US–USSR opinion starts strongly negative; arms spending is high."},{"decision":"order","option":"concert","text":"US, USSR, UK and France sign trade agreements and non-aggression pacts; trust rises."},{"decision":"aid","option":"all","text":"All European countries gain treasury and stability; US relations improve across Europe."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('different-peace-1945', 'order', 'What post-war order emerges?', '[{"id":"coldwar","label":"Cold War (historical)","description":"Rival blocs, low trust between the US and USSR.","historical":true},{"id":"concert","label":"Great-power concert","description":"The Allies keep cooperating through the UN; trade agreements and non-aggression pacts."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('different-peace-1945', 'aid', 'How is reconstruction funded?', '[{"id":"west","label":"Western Europe only (historical)","description":"Aid strengthens the Western bloc.","historical":true},{"id":"all","label":"Pan-European reconstruction","description":"Aid reaches all of Europe including the Soviet zone."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
