insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('byzantium-rises', 'The Second Dawn of Byzantium', 'What if the Byzantine Empire had survived — exploiting the Ottoman collapse after Ankara?', 1402, '1400', '{"id":"byzantium-rises","title":"The Second Dawn of Byzantium","subtitle":"Constantinople, 1402","question":"What if the Byzantine Empire had survived — exploiting the Ottoman collapse after Ankara?","mapKey":"1400","start":{"y":1402,"m":7},"era":"medieval","artHue":280,"background":["By 1400 the Byzantine Empire was reduced to Constantinople, parts of the Peloponnese and a few islands, and paid tribute to the Ottomans. Sultan Bayezid I had been besieging the city.","Timur''s victory at Ankara in July 1402 shattered Ottoman power and triggered a civil war among Bayezid''s sons. Byzantium briefly regained Thessaloniki through the Treaty of Gallipoli (1403).","The window closed: the Ottomans reunified in 1413 and Mehmed II conquered Constantinople on 29 May 1453."],"sourcesNote":"Background follows standard accounts (e.g. D. Nicol, \"The Last Centuries of Byzantium\", 1993). Borders: historical-basemaps c.1400.","focusCountries":["Byzantine Empire","Ottoman Empire","Kingdom of Hungary","Timurid Empire","Trebizond","Mamluke Sultanate"],"recommended":"Byzantine Empire","characters":[{"name":"Manuel II Palaiologos","role":"Byzantine Emperor","years":"1350–1425","bio":"Toured Western Europe seeking aid.","country":"Byzantine Empire"},{"name":"Süleyman Çelebi","role":"Ottoman prince in Rumelia","years":"c.1377–1411","bio":"Signed the Treaty of Gallipoli (1403).","country":"Ottoman Empire"},{"name":"Sigismund of Luxembourg","role":"King of Hungary","years":"1368–1437","bio":"Led the failed crusade of Nicopolis (1396).","country":"Kingdom of Hungary"}],"originalTimeline":[{"date":{"y":1402,"m":6},"title":"Battle of Ankara","text":"Ottoman defeat by Timur; Bayezid captured.","countries":["Ottoman Empire","Timurid Empire"]},{"date":{"y":1403,"m":1},"title":"Treaty of Gallipoli","text":"Thessaloniki and coastal lands returned to Byzantium.","countries":["Byzantine Empire","Ottoman Empire"]},{"date":{"y":1413,"m":6},"title":"Ottoman reunification","text":"Mehmed I ends the Interregnum.","countries":["Ottoman Empire"]},{"date":{"y":1430,"m":2},"title":"Fall of Thessaloniki","text":"The Ottomans take Thessaloniki from Venice.","countries":["Ottoman Empire"]},{"date":{"y":1453,"m":4},"title":"Fall of Constantinople","text":"Mehmed II captures the city; the last emperor dies defending it.","countries":["Byzantine Empire","Ottoman Empire"]}],"decisions":[{"id":"gallipoli","question":"How much does Byzantium recover in 1403?","context":"Historically: Thessaloniki and a coastal strip.","options":[{"id":"historical","label":"Treaty of Gallipoli terms (historical)","description":"Modest recovery.","historical":true},{"id":"offensive","label":"Aggressive reconquest","description":"Byzantium declares war on the divided Ottomans to reclaim Thrace."}]},{"id":"union","question":"Does Byzantium secure Western help?","context":"Church union was deeply divisive.","options":[{"id":"none","label":"Little Western aid (historical)","description":"Byzantium fights largely alone.","historical":true},{"id":"alliance","label":"Alliance with Hungary","description":"A Hungarian–Byzantine alliance against the Ottomans."}]}],"consequences":[{"decision":"gallipoli","option":"offensive","text":"War with the Ottoman Empire, which suffers a severe civil-war stability penalty."},{"decision":"union","option":"alliance","text":"Byzantium and Hungary form an alliance; Byzantine treasury receives Western subsidies."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('byzantium-rises', 'gallipoli', 'How much does Byzantium recover in 1403?', '[{"id":"historical","label":"Treaty of Gallipoli terms (historical)","description":"Modest recovery.","historical":true},{"id":"offensive","label":"Aggressive reconquest","description":"Byzantium declares war on the divided Ottomans to reclaim Thrace."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('byzantium-rises', 'union', 'Does Byzantium secure Western help?', '[{"id":"none","label":"Little Western aid (historical)","description":"Byzantium fights largely alone.","historical":true},{"id":"alliance","label":"Alliance with Hungary","description":"A Hungarian–Byzantine alliance against the Ottomans."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
