insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('vienna-1683', 'The Gates of Vienna', 'What if the Ottomans had taken Vienna in 1683?', 1683, '1650', '{"id":"vienna-1683","title":"The Gates of Vienna","subtitle":"Central Europe, 1683","question":"What if the Ottomans had taken Vienna in 1683?","mapKey":"1650","start":{"y":1683,"m":6},"era":"renaissance","artHue":140,"background":["In July 1683 Grand Vizier Kara Mustafa Pasha besieged Vienna, capital of the Habsburg monarchy, with a large Ottoman army.","On 12 September a relief army led by King Jan III Sobieski of Poland–Lithuania defeated the besiegers. The Great Turkish War followed, ending in 1699 with the Treaty of Karlowitz and the loss of Hungary."],"sourcesNote":"Background follows standard accounts (e.g. A. Wheatcroft, \"The Enemy at the Gate\", 2008). Borders: historical-basemaps 1650 (the nearest available dataset, labelled as approximate for 1683).","focusCountries":["Ottoman Empire","Holy Roman Empire","Polish–Lithuanian Commonwealth","Venice","France","Tsardom of Muscovy"],"recommended":"Ottoman Empire","characters":[{"name":"Kara Mustafa Pasha","role":"Ottoman Grand Vizier","years":"1634/35–1683","bio":"Commanded the siege; executed after the defeat.","country":"Ottoman Empire"},{"name":"Leopold I","role":"Holy Roman Emperor","years":"1640–1705","bio":"Fled Vienna during the siege.","country":"Holy Roman Empire"},{"name":"Jan III Sobieski","role":"King of Poland","years":"1629–1696","bio":"Led the relief at the Battle of Vienna.","country":"Polish–Lithuanian Commonwealth"},{"name":"Louis XIV","role":"King of France","years":"1638–1715","bio":"Rival of the Habsburgs; stayed out of the relief.","country":"France"}],"originalTimeline":[{"date":{"y":1683,"m":6},"title":"Siege of Vienna begins","text":"The Ottoman army invests the city (14 July).","countries":["Ottoman Empire","Holy Roman Empire"]},{"date":{"y":1683,"m":8},"title":"Battle of Vienna","text":"Sobieski''s relief army routs the Ottomans (12 September).","countries":["Polish–Lithuanian Commonwealth","Ottoman Empire"]},{"date":{"y":1684,"m":2},"title":"Holy League","text":"Habsburgs, Poland and Venice ally against the Ottomans.","countries":["Holy Roman Empire","Polish–Lithuanian Commonwealth","Venice"]},{"date":{"y":1699,"m":0},"title":"Treaty of Karlowitz","text":"The Ottomans cede most of Hungary.","countries":["Ottoman Empire"]}],"decisions":[{"id":"siege","question":"How does the siege end?","context":"September 1683.","options":[{"id":"relieved","label":"Relieved by Sobieski (historical)","description":"Ottoman defeat and counter-offensive.","historical":true},{"id":"falls","label":"Vienna falls","description":"The Ottomans take Vienna before the relief arrives."}]},{"id":"france","question":"What does France do?","context":"Louis XIV was hostile to the Habsburgs.","options":[{"id":"neutral","label":"Neutral (historical)","description":"France stays out.","historical":true},{"id":"opportunist","label":"France attacks the Habsburgs","description":"France exploits the crisis on the Rhine."}]}],"consequences":[{"decision":"siege","option":"relieved","text":"Ottoman morale and stability fall; a Holy League forms against them."},{"decision":"siege","option":"falls","text":"The Vienna province passes to Ottoman control; Habsburg stability collapses."},{"decision":"france","option":"opportunist","text":"France declares war on the Holy Roman Empire."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('vienna-1683', 'siege', 'How does the siege end?', '[{"id":"relieved","label":"Relieved by Sobieski (historical)","description":"Ottoman defeat and counter-offensive.","historical":true},{"id":"falls","label":"Vienna falls","description":"The Ottomans take Vienna before the relief arrives."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('vienna-1683', 'france', 'What does France do?', '[{"id":"neutral","label":"Neutral (historical)","description":"France stays out.","historical":true},{"id":"opportunist","label":"France attacks the Habsburgs","description":"France exploits the crisis on the Rhine."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('vienna-1683', 1683, 6, 'Siege of Vienna begins', 'The Ottoman army invests the city (14 July).', '{"Ottoman Empire","Holy Roman Empire"}', true);
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('vienna-1683', 1683, 8, 'Battle of Vienna', 'Sobieski''s relief army routs the Ottomans (12 September).', '{"Polish–Lithuanian Commonwealth","Ottoman Empire"}', true);
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('vienna-1683', 1684, 2, 'Holy League', 'Habsburgs, Poland and Venice ally against the Ottomans.', '{"Holy Roman Empire","Polish–Lithuanian Commonwealth","Venice"}', true);
insert into public.historical_events (scenario_id, year, month, title, description, countries, is_documented) values ('vienna-1683', 1699, 0, 'Treaty of Karlowitz', 'The Ottomans cede most of Hungary.', '{"Ottoman Empire"}', true);
insert into public.scenario_definitions (id, title, question, start_year, map_key, definition, is_public, is_builtin) values ('inca-resists', 'Sun Over the Andes', 'What if the Inca Empire had resisted the Spanish conquest?', 1530, '1530', '{"id":"inca-resists","title":"Sun Over the Andes","subtitle":"Tawantinsuyu, 1530","question":"What if the Inca Empire had resisted the Spanish conquest?","mapKey":"1530","start":{"y":1530,"m":0},"era":"renaissance","artHue":28,"background":["By 1530 the Inca Empire (Tawantinsuyu) stretched over 4,000 km along the Andes. Smallpox, spreading ahead of the Europeans, killed Emperor Huayna Capac and his heir around 1527.","A civil war between his sons Huáscar and Atahualpa devastated the empire. Atahualpa had just won when Francisco Pizarro''s small expedition captured him at Cajamarca in November 1532; he was executed in 1533.","The conquest brought catastrophic demographic collapse from epidemics, war and forced labour."],"sourcesNote":"Background follows standard accounts (e.g. J. Hemming, \"The Conquest of the Incas\", 1970). Borders: historical-basemaps 1530.","sensitivity":"The conquest and colonisation of the Americas involved mass death, enslavement and forced labour (e.g. the mita and encomienda). The simulation treats these as documented harms.","focusCountries":["Inca Empire","Spain","Viceroyalty of New Spain","Portugal"],"recommended":"Inca Empire","characters":[{"name":"Atahualpa","role":"Sapa Inca","years":"c.1502–1533","bio":"Won the civil war against Huáscar; captured at Cajamarca.","country":"Inca Empire"},{"name":"Huáscar","role":"Sapa Inca (rival)","years":"c.1503–1532","bio":"Ruled from Cusco; killed on Atahualpa''s orders.","country":"Inca Empire"},{"name":"Francisco Pizarro","role":"Spanish conquistador","years":"c.1478–1541","bio":"Led the conquest of Peru.","country":"Spain"},{"name":"Charles V","role":"King of Spain, Holy Roman Emperor","years":"1500–1558","bio":"Authorised the expedition.","country":"Spain"}],"originalTimeline":[{"date":{"y":1529,"m":0},"title":"Inca civil war","text":"Huáscar and Atahualpa fight for the throne.","countries":["Inca Empire"]},{"date":{"y":1532,"m":10},"title":"Cajamarca","text":"Pizarro captures Atahualpa (16 November).","countries":["Inca Empire","Spain"]},{"date":{"y":1533,"m":6},"title":"Execution of Atahualpa","text":"Atahualpa is executed despite paying a huge ransom.","countries":["Inca Empire"]},{"date":{"y":1533,"m":10},"title":"Fall of Cusco","text":"The Spanish enter the Inca capital.","countries":["Inca Empire","Spain"]},{"date":{"y":1572,"m":8},"title":"Fall of Vilcabamba","text":"The last Inca state is destroyed; Túpac Amaru executed.","countries":["Inca Empire"]}],"decisions":[{"id":"civilwar","question":"Is the Inca civil war avoided?","context":"The succession war weakened the empire just before contact.","options":[{"id":"war","label":"Civil war (historical)","description":"Severe instability and losses.","historical":true},{"id":"peace","label":"Brothers share power","description":"A negotiated division prevents the civil war."}]},{"id":"cajamarca","question":"What happens at Cajamarca?","context":"November 1532.","options":[{"id":"captured","label":"Atahualpa captured (historical)","description":"Spanish war against a leaderless empire.","historical":true},{"id":"ambush_fails","label":"The ambush fails","description":"Pizarro''s expedition is destroyed; Spain must decide whether to send more."}]},{"id":"epidemic","question":"How hard do European diseases hit?","context":"Smallpox had already struck c.1527.","options":[{"id":"severe","label":"Severe epidemics (historical)","description":"Waves of smallpox and other diseases.","historical":true},{"id":"milder","label":"Milder outbreaks","description":"Epidemics still occur but with lower severity."}]}],"consequences":[{"decision":"civilwar","option":"war","text":"Inca stability and manpower start low."},{"decision":"cajamarca","option":"captured","text":"Spain declares war on the Inca in 1532; Inca legitimacy collapses."},{"decision":"cajamarca","option":"ambush_fails","text":"Spain''s first expedition fails; Inca morale rises."},{"decision":"epidemic","option":"severe","text":"A severe smallpox epidemic strikes the Inca Empire."}]}'::jsonb, true, true) on conflict (id) do update set definition = excluded.definition;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('inca-resists', 'civilwar', 'Is the Inca civil war avoided?', '[{"id":"war","label":"Civil war (historical)","description":"Severe instability and losses.","historical":true},{"id":"peace","label":"Brothers share power","description":"A negotiated division prevents the civil war."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('inca-resists', 'cajamarca', 'What happens at Cajamarca?', '[{"id":"captured","label":"Atahualpa captured (historical)","description":"Spanish war against a leaderless empire.","historical":true},{"id":"ambush_fails","label":"The ambush fails","description":"Pizarro''s expedition is destroyed; Spain must decide whether to send more."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
insert into public.scenario_decisions (scenario_id, decision_key, question, options, depends_on) values ('inca-resists', 'epidemic', 'How hard do European diseases hit?', '[{"id":"severe","label":"Severe epidemics (historical)","description":"Waves of smallpox and other diseases.","historical":true},{"id":"milder","label":"Milder outbreaks","description":"Epidemics still occur but with lower severity."}]'::jsonb, null) on conflict (scenario_id, decision_key) do nothing;
